using System;using System.IO;using System.Linq;using System.Reflection;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
[InitializeOnLoad]public static class CoffeeTextureVerify{static CoffeeTextureVerify(){EditorApplication.update+=Poll;}static void Poll(){if(EditorApplication.isCompiling||!File.Exists("CoffeeTextureVerify.request"))return;File.Delete("CoffeeTextureVerify.request");try{var s=SceneManager.GetSceneByPath("Assets/Editor/DayNightBackups/Gangstar Final Env.unity");var flags=BindingFlags.Static|BindingFlags.NonPublic;var capture=typeof(FinalPNGCityDetails).GetMethod("Capture",flags);var fs=s.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<MeshFilter>()).Where(f=>f.name.StartsWith("Circus_Circus_0")).OrderByDescending(f=>f.transform.position.x).ToArray();foreach(int k in new[]{0,1}){var c=fs[k].GetComponent<Renderer>().bounds.center;capture.Invoke(null,new object[]{s,c+new Vector3(0,-1,57),c+Vector3.down*4,"Coffee-Texture-Only-"+(k+1)+"-Front"});if(k==0)capture.Invoke(null,new object[]{s,c+new Vector3(0,-1,-57),c+Vector3.down*4,"Coffee-Texture-Only-1-Back"});}var close=fs[0].GetComponent<Renderer>().bounds.center;capture.Invoke(null,new object[]{s,close+new Vector3(12,-5,43),close+Vector3.down*6,"Coffee-Refined-Window-Closeup"});var mat=fs[0].GetComponent<Renderer>().sharedMaterial;File.WriteAllText("FinalEnvironmentRoadReview/CoffeeWindowShaderCheck.txt","Coffee shared shader errors="+ShaderUtil.ShaderHasError(mat.shader));File.AppendAllText("FinalEnvironmentRoadReview/CoffeeTextureRepair.txt","\nVerified both shops and captured front/back views after atlas import.");}catch(Exception e){File.AppendAllText("FinalEnvironmentRoadReview/CoffeeTextureRepair.txt",e.ToString());}}}
